28: const ITEMS = {
29:   leafcloak:{name:'Capa de folhas',icon:'🍃',description:'Uma capa leve tecida com folhas resistentes.',effect:'+8 energia máxima · +2 defesa',maxHp:8,defense:2},
30:   berry:{name:'Baga Oran',icon:'🫐',description:'Uma fruta fresca que restaura energia.',effect:'Recupera até 35 de energia',heal:35},
31:   twigcrown:{name:'Coroa de galhos',icon:'👑',description:'Uma pequena coroa de galhos flexíveis.',effect:'+3 ataque',attack:3},
32:   scarf:{name:'Cachecol de viagem',icon:'🧣',description:'Cachecol macio para os dias frios.',effect:'+5 energia máxima',maxHp:5},
33:   goggles:{name:'Óculos de explorador',icon:'🥽',description:'Óculos usados por viajantes experientes.',effect:'+2 ataque · +1 defesa',attack:2,defense:1},
34:   medal:{name:'Medalha da floresta',icon:'🏅',description:'Um símbolo de coragem e amizade.',effect:'+4 energia máxima · +1 ataque',maxHp:4,attack:1}
